"""Checksum vectors from official FreeBSD pkg 2.8.4, plus refusal guards."""
import base64
import importlib.util
import os
from pathlib import Path
import tempfile
import unittest
from unittest import mock

SOURCE = Path(__file__).resolve().parents[1] / 'system/freebsd/image/pkg_checksum.py'
SPEC = importlib.util.spec_from_file_location('freebsd_image_pkg_checksum', SOURCE)
checksum = importlib.util.module_from_spec(SPEC)
SPEC.loader.exec_module(checksum)

# Official tests/lib/checksum.c check_files vectors, not generated by this code.
BAR_BLAKE2 = '2$gf8mcrnmm6p6hg6wa9xkfb98zo8g6nxu8z4q7s93boz8hzf5ogrsr4qgpsb7utd6speio3op18ocyrsa9ms8jj15byttiq7ofbih8gn'
BAR_BLAKE2S = '5$dqi4rzroazhfbq4sd33ektsg3jjsrye7mc37ggsa9bt3mhxsyddy'
BAR_SHA256 = '7d865e959b2466918c9863afca942d0fb89d7c9ac0c99bafc3749504ded97730'
A_BLAKE2 = '2$u3xsc8fhkf9ntjikcz3hcsg1h5n59yqmz8s483emc8gessm4qnpk7ikhgqcmmz98ci391sdx565bazeffh1djkzkep7j1qqgeawsc6y'

# Independently captured from the actual ARM64 FreeBSD pkg database and files;
# original bounded read-only command report: build/freebsd-pkg-checksum-golden-r10.json.
ARM_GOLDENS = (
    ('2to3-3.12',
     '2$xug35qmfi1663c5zpdwr48ihg3xb7fbeu3n8ofgmbiopsdhxe4cz8jkz56xchd4q61fhmgx16cqzbmy6zihudoyrgxsmqhoxezoue3d',
     'IyEvdXNyL2xvY2FsL2Jpbi9weXRob24zLjEyCmltcG9ydCBzeXMKZnJvbSBsaWIydG8zLm1haW4gaW1wb3J0IG1haW4KCnN5cy5leGl0KG1haW4oImxpYjJ0bzMuZml4ZXMiKSkK'),
    ('idle3.12',
     '2$z4kkp48ogjoy8gwpx7tuq1uebtbnjyrpfbn57fo93w9z49t5tyyzon8b5oj4k1f373kgdng9girmqrau6rxt3pxs4ha4jdjgtmk731b',
     'IyEvdXNyL2xvY2FsL2Jpbi9weXRob24zLjEyCgpmcm9tIGlkbGVsaWIucHlzaGVsbCBpbXBvcnQgbWFpbgppZiBfX25hbWVfXyA9PSAnX19tYWluX18nOgogICAgbWFpbigpCg=='),
)


class PkgChecksumTests(unittest.TestCase):
    def setUp(self):
        self.temp = tempfile.TemporaryDirectory()
        self.root = Path(self.temp.name)
        self.path = self.root / 'data'
        self.path.write_bytes(b'bar\n')

    def tearDown(self):
        self.temp.cleanup()

    def test_official_regular_file_blake2b512_vector_and_sha256(self):
        result = checksum.verify_declared(self.path, BAR_BLAKE2)
        self.assertTrue(result['verified'])
        self.assertEqual(result['algorithm'], 'blake2b-512')
        self.assertEqual(result['sha256'], BAR_SHA256)
        self.assertEqual(result['bytes'], 4)

    def test_other_confirmed_textual_file_formats(self):
        for value, algorithm in ((BAR_BLAKE2S, 'blake2s-256'), (BAR_SHA256, 'sha256'),
                                 ('1$' + BAR_SHA256, 'sha256')):
            with self.subTest(value=value):
                self.assertEqual(checksum.verify_declared(self.path, value)['algorithm'], algorithm)

    def test_official_data_a_blake2_vector(self):
        self.path.write_bytes(b'a')
        self.assertTrue(checksum.verify_declared(self.path, A_BLAKE2)['verified'])

    def test_actual_arm64_guest_declared_pkg_checksums(self):
        for name, declared, encoded in ARM_GOLDENS:
            with self.subTest(name=name):
                data = base64.b64decode(encoded, validate=True)
                self.path.write_bytes(data)
                result = checksum.verify_declared(self.path, declared)
                self.assertTrue(result['verified'])
                self.assertEqual(result['bytes'], len(data))

    def test_lsb_encoding_is_not_standard_zbase32(self):
        self.assertEqual(checksum._base32(b'\x01'), 'by')
        self.assertEqual(checksum._base32(b'\xff'), '98')
        self.assertEqual(checksum._base32(bytes(range(5))), 'yeyroboy')

    def test_malformed_types_package_digests_and_noncanonical_padding_refused(self):
        bad = (None, '', '2$', '02$' + BAR_BLAKE2[2:], '2$2$' + BAR_BLAKE2[2:],
               '3$abc', '4$abc', '6$abc', '9$abc', BAR_SHA256.upper(),
               BAR_BLAKE2 + '\n', '2$' + 'y' * 102 + '9', '2$' + 'Y' * 103,
               '2$' + 'y' * 104, '2$' + 'y' * 102)
        for value in bad:
            with self.subTest(value=value):
                with self.assertRaises(ValueError):
                    checksum.verify_declared(self.path, value)

    def test_mismatch_refused(self):
        self.path.write_bytes(b'changed')
        with self.assertRaisesRegex(ValueError, 'mismatch'):
            checksum.verify_declared(self.path, BAR_BLAKE2)

    def test_symlink_and_directory_refused(self):
        alias = self.root / 'alias'
        alias.symlink_to(self.path.name)
        for path in (alias, self.root):
            with self.subTest(path=path):
                with self.assertRaisesRegex(ValueError, 'regular'):
                    checksum.verify_declared(path, BAR_BLAKE2)

    def test_parent_symlink_refused(self):
        alias = self.root / 'linked'
        alias.symlink_to(self.root, target_is_directory=True)
        with self.assertRaisesRegex(ValueError, 'parent'):
            checksum.verify_declared(alias / self.path.name, BAR_BLAKE2)

    def test_size_bound_refused_before_read(self):
        with mock.patch.object(checksum, 'MAX_FILE_BYTES', 3):
            with self.assertRaisesRegex(ValueError, 'bounded'):
                checksum.verify_declared(self.path, BAR_BLAKE2)

    def test_change_during_streaming_is_refused(self):
        original_read = os.read
        changed = False
        def mutate(fd, count):
            nonlocal changed
            block = original_read(fd, count)
            if block and not changed:
                changed = True
                with self.path.open('ab') as writer:
                    writer.write(b'changed')
            return block
        with mock.patch.object(checksum.os, 'read', side_effect=mutate):
            with self.assertRaisesRegex(ValueError, 'changed during'):
                checksum.verify_declared(self.path, BAR_BLAKE2)


if __name__ == '__main__':
    unittest.main()
